using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notepad = new Notepad();

var tools = new[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
        {
            return WebSearch.SearchAsync(query);
        },
        "web_search",
        "Search the web for information on a topic. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("The note text to save")] string note) =>
        {
            notepad.Add(note);
            return $"Note saved. You now have {notepad.Count} note(s).";
        },
        "save_note",
        "Save a research note for later reference."),

    AIFunctionFactory.Create(
        () => notepad.Count == 0
            ? "No notes saved yet."
            : string.Join("\n---\n", notepad.Notes.Select((n, i) => $"[{i + 1}] {n}")),
        "list_notes",
        "List all saved research notes."),

    AIFunctionFactory.Create(
        () => { notepad.Clear(); return "All notes cleared."; },
        "clear_notes",
        "Clear all saved research notes."),
};

// ---------------------------------------------------------------------------
// Chat client with automatic tool invocation
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

const string systemPrompt = """
    You are a research agent. The user will give you a topic to research.

    Your workflow:
    1. Break the topic into 2-3 focused search queries.
    2. Use the web_search tool for each query.
    3. Use save_note to record key findings from each search.
    4. After all searches, use list_notes to review your notes.
    5. Produce a final, well-structured summary of your research with references.

    Be thorough but concise. Cite sources where possible.
    """;

var history = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
};

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------
Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine("  Research Agent  (type 'exit' to quit)");
Console.WriteLine("═══════════════════════════════════════════");

while (true)
{
    Console.Write("\nTopic> ");
    var input = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(input) || input.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    history.Add(new ChatMessage(ChatRole.User, input));

    Console.WriteLine();
    var response = await client.GetResponseAsync(history, chatOptions);
    history.AddRange(response.Messages);

    Console.WriteLine(response.Text);

    // Reset notes for the next topic
    notepad.Clear();
}

Console.WriteLine("\nGoodbye!");

